# Behind Caddy. DOMAIN is the machine's domain. The proxy header is
# JSON, which a service env line cannot hold: a quote is not a word.
# Group write on the library comes from paperless-group.so: SQLite asks
# for mode 0644, which has none. This keeps other users from writing.
import os

os.umask(0o007)

os.environ.setdefault(
    "PAPERLESS_PROXY_SSL_HEADER",
    '["HTTP_X_FORWARDED_PROTO","https"]',
)
domain = os.environ.get("DOMAIN", "")
if domain and "PAPERLESS_URL" not in os.environ:
    os.environ["PAPERLESS_URL"] = "https://" + domain
